def shortest_basket_cover(tape, basket):
    need = {}
    for t in basket:
        need[t] = need.get(t, 0) + 1
    missing = len(basket)
    best = None
    left = 0
    for right, t in enumerate(tape):
        if t in need:
            if need[t] > 0:
                missing -= 1
            need[t] -= 1
        while missing == 0:
            if best is None or right - left < best[1] - best[0]:
                best = (left, right)
            u = tape[left]
            if u in need:
                need[u] += 1
                if need[u] > 0:
                    missing += 1
            left += 1
    return best

